async function initFocus(){
 const host=document.getElementById('focus-picker'); if(!host)return;
 const pets=await (await fetch('/pet-options')).json(); let chosen=null;
 host.innerHTML='<h2>Choose your downgrade focus</h2><p class="focus-note">Pick the pet you want to give, then its exact variant. Matching opportunities get their own section; all other profitable trades stay visible.</p><input id="focus-search" class="search-box" placeholder="Search 800+ pets…" aria-label="Search target pets"><div class="focus-grid" id="focus-grid"></div><div class="focus-controls"><select id="focus-variant" aria-label="Target variant"><option>Choose a pet first</option></select><button type="button" class="accept-btn" id="focus-save">Focus this pet</button><button type="button" class="accept-btn" id="focus-clear">Clear focus</button><span id="focus-current" class="focus-note"></span></div>';
 const grid=host.querySelector('#focus-grid'), search=host.querySelector('#focus-search'), variants=host.querySelector('#focus-variant'), note=host.querySelector('#focus-current');
 function draw(){grid.replaceChildren();pets.filter(p=>p.name.toLowerCase().includes(search.value.toLowerCase())).slice(0,80).forEach(p=>{const b=document.createElement('button');b.type='button';b.className='focus-pet'+(chosen===p?' selected':'');const im=document.createElement('img');im.src=p.image;im.alt='';im.loading='lazy';b.append(im,document.createTextNode(p.name));b.onclick=()=>{chosen=p;variants.replaceChildren();Object.keys(p.variants).forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v||'Normal • no potions';variants.append(o)});draw()};grid.append(b)})}
 async function save(value){const r=await fetch('/set_target',{method:'POST',body:new URLSearchParams({target_pet:value})});if(!r.ok){note.textContent='Could not save focus. Try again.';return}note.textContent=value?'Focused: '+value:'Showing all opportunities';const hidden=document.getElementById('focus-hidden');if(hidden)hidden.value=value;window.dispatchEvent(new CustomEvent('downgrade-focus',{detail:value}));}
 search.oninput=draw;host.querySelector('#focus-save').onclick=()=>{if(chosen)save(chosen.name+(variants.value?' '+variants.value:''))};host.querySelector('#focus-clear').onclick=()=>save('');draw();
}
initFocus().catch(console.error);
